import re

_encoding_re = re.compile(r'charset=([a-zA-Z0-9_-]+)')

def parse_encoding_header(header_value: str) -> str:
    if not header_value:
        return 'utf-8'
    # Bounded length parsing prevents catastrophic regex backtrack
    match = _encoding_re.search(header_value[:256])
    if match:
        return match.group(1).lower()
    return 'utf-8'
